/// The step names of the Japanese screen (the words of the table the app shows: `query.step-name.<id>`).
fn japanese_names() -> HashMap<String, String> {
    include_str!("../../../ibis-office-base/i18n/ja/xlsx.tsv")
        .lines()
        .filter_map(|l| l.strip_prefix("query.step-name."))
        .filter_map(|l| l.split_once('\t'))
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect()
}

#[test]
fn what_excel_writes_is_read_and_written_back_the_same() {
    let names = japanese_names();
    let name_of = |id: &str| names.get(id).cloned().unwrap_or_else(|| english_step_name(id).to_string());
    let base = Query::new("Q", Source::Blank);
    for (file, code) in EXCEL_M {
        let query = match m_to_query(code, &base) {
            Ok(q) => q,
            Err(e) => panic!("{file}: {e:?}"),
        };
        let back = query_to_m_named(&query, &name_of);
        assert_eq!(&back, code, "{file}\nsteps: {:?}", query.steps);
    }
}

/// What the screen's steps write when they were made by the screen (not read from code): type changes of columns the step before does
/// not hold go into it, as Excel does; a column held already begins another step.
#[test]
fn steps_made_on_the_screen_are_written_as_excel_writes_them() {
    let ty = |column: &str, ty: QType| Step::ChangeType { column: column.to_string(), ty, culture: Culture::Invariant, apart: false };
    let mut q = Query::new("Q", Source::Table("T".to_string()));
    q.steps = vec![ty("a", QType::Text), ty("b", QType::Whole), ty("a", QType::Whole), Step::AlternateRows { offset: 1, skip: 1, take: 1 }, Step::KeepRange { offset: 1, count: Some(1) }];
    let m = query_to_m(&q);
    assert!(m.contains("#\"Changed Type\" = Table.TransformColumnTypes(Source,{{\"a\", type text}, {\"b\", Int64.Type}})"), "{m}");
    assert!(m.contains("#\"Changed Type1\" = Table.TransformColumnTypes(#\"Changed Type\",{{\"a\", Int64.Type}})"), "{m}");
    assert!(m.contains("Table.AlternateRows(#\"Changed Type1\",1,1,1)") && m.contains("Table.Range(#\"Removed Alternate Rows\",1,1)"), "{m}");
    // The same code read back is the same steps.
    assert_eq!(m_to_query(&m, &q).unwrap().steps, q.steps);
    // The checkboxes of a column are written in brackets, the next column's after an `and`; three conditions of the 詳細設定 have none.
    let leaf = |c: &str, v: &str| Cond::Leaf { column: c.to_string(), op: Op::Equals, value: v.to_string() };
    let boxed = Cond::And(vec![Cond::Group(Box::new(leaf("a", "1"))), Cond::Group(Box::new(Cond::Or(vec![leaf("b", "x"), leaf("b", "y")])))]);
    assert_eq!(super::text_m::cond_text(&boxed), "([a] = 1) and ([b] = \"x\" or [b] = \"y\")");
    let advanced = Cond::Or(vec![Cond::And(vec![leaf("a", "1"), leaf("b", "2")]), leaf("c", "3")]);
    assert_eq!(super::text_m::cond_text(&advanced), "[a] = 1 and [b] = 2 or [c] = 3");
}

/// The values Excel's Power Query gave the splitters (`tasks/doc/requests/2026-11-16-k0039-split-semantics-result.md`, section A, evaluated in
/// Excel): remainders are dropped, a count from the end cuts from the end, and the pieces keep the text's order.
#[test]
fn the_splitters_give_what_excel_gives() {
    use super::cond::split_text;
    let s = |t: &str, by: SplitBy| split_text(t, &by);
    assert_eq!(s("abcdefgh", SplitBy::Lengths { lengths: vec![2, 3], from_end: false }), ["ab", "cde"]);
    assert_eq!(s("abcdefgh", SplitBy::Lengths { lengths: vec![2, 3], from_end: true }), ["def", "gh"]);
    assert_eq!(s("abcdefgh", SplitBy::Positions { positions: vec![2, 5], from_end: false }), ["cde", "fgh"]);
    assert_eq!(s("AppleRed-L-1", SplitBy::Positions { positions: vec![0, 5], from_end: true }), ["AppleRe", "d-L-1"]);
    assert_eq!(s("AppleRed-L-1", SplitBy::Positions { positions: vec![0, 5], from_end: false }), ["Apple", "Red-L-1"]);
    assert_eq!(s("AppleRed-L-1", SplitBy::Transition { from: CharClass::Lower, to: CharClass::Upper }), ["Apple", "Red-L-1"]);
    assert_eq!(s("AppleRed-L-1", SplitBy::Transition { from: CharClass::Upper, to: CharClass::Lower }), ["A", "ppleR", "ed-L-1"]);
    assert_eq!(s("AppleRed-L-1", SplitBy::Transition { from: CharClass::Digit, to: CharClass::NonDigit }), ["AppleRed-L-1"]);
    assert_eq!(s("AppleRed-L-1", SplitBy::Transition { from: CharClass::NonDigit, to: CharClass::Digit }), ["AppleRed-L-", "1"]);
}

/// The names Excel gave the steps of the Power Query editor's operations (the same file, section B): in Japanese (the screen's names) and in
/// English (`english_step_name`).
#[test]
fn the_steps_are_named_as_excel_names_them() {
    let ja = japanese_names();
    for (id, japanese, english) in [
        ("kept-first-rows", "\u{4fdd}\u{5b58}\u{3055}\u{308c}\u{305f}\u{5148}\u{982d}\u{884c}", "Kept First Rows"),
        ("removed-duplicates", "\u{524a}\u{9664}\u{3055}\u{308c}\u{305f}\u{91cd}\u{8907}", "Removed Duplicates"),
        ("replaced-value", "\u{7f6e}\u{304d}\u{63db}\u{3048}\u{3089}\u{308c}\u{305f}\u{5024}", "Replaced Value"),
        ("pivoted-column", "\u{30d4}\u{30dc}\u{30c3}\u{30c8}\u{3055}\u{308c}\u{305f}\u{5217}", "Pivoted Column"),
        ("merged-queries", "\u{30de}\u{30fc}\u{30b8}\u{3055}\u{308c}\u{305f}\u{30af}\u{30a8}\u{30ea}\u{6570}", "Merged Queries"),
        ("inserted-text-length", "\u{633f}\u{5165}\u{3055}\u{308c}\u{305f}\u{30c6}\u{30ad}\u{30b9}\u{30c8}\u{306e}\u{9577}\u{3055}", "Inserted Text Length"),
        ("inserted-absolute-value", "\u{633f}\u{5165}\u{3055}\u{308c}\u{305f}\u{7d76}\u{5bfe}\u{5024}", "Inserted Absolute Value"),
        ("inserted-square-root", "\u{633f}\u{5165}\u{3055}\u{308c}\u{305f}\u{5e73}\u{65b9}\u{6839}", "Inserted Square Root"),
        ("kept-range", "\u{4fdd}\u{5b58}\u{3055}\u{308c}\u{305f}\u{884c}\u{7bc4}\u{56f2}", "Kept Range of Rows"),
        ("removed-alternate-rows", "\u{524a}\u{9664}\u{3055}\u{308c}\u{305f}\u{4ee3}\u{66ff}\u{884c}", "Removed Alternate Rows"),
        ("duplicated-column", "\u{91cd}\u{8907}\u{3055}\u{308c}\u{305f}\u{5217}", "Duplicated Column"),
        ("added-index", "\u{8ffd}\u{52a0}\u{3055}\u{308c}\u{305f}\u{30a4}\u{30f3}\u{30c7}\u{30c3}\u{30af}\u{30b9}", "Added Index"),
    ] {
        assert_eq!(ja.get(id).map(String::as_str), Some(japanese), "{id} in Japanese");
        assert_eq!(english_step_name(id), english, "{id} in English");
    }
    // A column Excel adds by 列の追加 → 抽出 / 指数 is named by what it holds.
    let mut q = Query::new("Q", Source::Table("T".to_string()));
    q.steps = vec![
        Step::AddColumn { name: "\u{9577}\u{3055}".to_string(), formula: "Text.Length([a])".to_string(), ty: Some(QType::Whole) },
        Step::AddColumn { name: "\u{7d76}\u{5bfe}\u{5024}".to_string(), formula: "Number.Abs([b])".to_string(), ty: Some(QType::Whole) },
        Step::AddColumn { name: "\u{5e73}\u{65b9}\u{6839}".to_string(), formula: "Number.Sqrt([b])".to_string(), ty: Some(QType::Decimal) },
    ];
    let m = query_to_m(&q);
    assert!(m.contains("#\"Inserted Text Length\" = ") && m.contains("#\"Inserted Absolute Value\" = ") && m.contains("#\"Inserted Square Root\" = "), "{m}");
}

/// A query whose source is `Csv.Document(File.Contents(…))` (what Excel's テキスト/CSV から writes) reads the file: the columns `Column1`…
/// are text, a field in quotes may hold the delimiter, line ends and a doubled quote, and 昇格されたヘッダー数 takes the first row for names.
#[cfg(not(target_family = "wasm"))]
#[test]
fn a_csv_source_is_read_from_its_file() {
    use crate::Presentation;
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/k0039-csv");
    std::fs::create_dir_all(&dir).unwrap();
    let file = dir.join("t.csv");
    std::fs::write(&file, "\u{feff}a,b\r\n1,\"x,\"\"y\"\"\"\r\n2,\r\n").unwrap();
    let source = Source::Csv { path: file.to_string_lossy().into_owned(), delimiter: ",".to_string(), columns: 2, encoding: 65001, quote: "Csv".to_string() };
    let table = super::book::read_source(&Presentation::default(), &source).unwrap();
    assert_eq!(table.columns.iter().map(|c| c.name.as_str()).collect::<Vec<_>>(), ["Column1", "Column2"]);
    assert_eq!(table.rows.len(), 3);
    assert_eq!(table.rows[1][1], ibis_calc::CellValue::Text("x,\"y\"".to_string()));
    assert_eq!(table.rows[2][1], ibis_calc::CellValue::Empty);
    // Another character code is named, not guessed.
    let other = Source::Csv { path: file.to_string_lossy().into_owned(), delimiter: ",".to_string(), columns: 2, encoding: 932, quote: "Csv".to_string() };
    assert!(super::book::read_source(&Presentation::default(), &other).unwrap_err().contains("932"));
    let _ = std::fs::remove_dir_all(&dir);
}
